code.java:
class Solution {
    public int findFinalValue(int[] nums,int original){
        Set<Integer> values=new HashSet<>();
        for(int value:nums)values.add(value);
        while(values.contains(original))original*=2;
        return original;
    }
}

code.kotlin:
class Solution {
    fun findFinalValue(nums:IntArray,originalValue:Int):Int{
        val values=nums.toHashSet();
        var original=originalValue;
        while(original in values)original*=2;
        return original
    }
}

code.cpp:
class Solution {
    public:int findFinalValue(vector<int>& nums,int original){
        unordered_set<int> values(nums.begin(),nums.end());
        while(values.count(original))original*=2;
        return original;
    }
};
